import pandas as pd
import json

df = pd.read_parquet("data.parquet")

# Parse the author column to extract username and count reviews
usernames_with_reviews = {}

for author_str in df['author']:
    try:
        author_dict = json.loads(author_str.replace("'", '"'))
        username = author_dict.get('username')
        num_reviews = author_dict.get('num_reviews')

        if username and num_reviews:
            if username not in usernames_with_reviews:
                usernames_with_reviews[username] = num_reviews
    except:
        pass

# Filter for usernames with more than 4 reviews
result = [username for username, num_reviews in usernames_with_reviews.items() if num_reviews > 4]

print(result)
