import pandas as pd

# Load the data
df = pd.read_parquet("data.parquet")

# Build a mapping of Unique ID to children
children_map = {}
for _, row in df.iterrows():
    parent_id = row['Parent']
    unique_id = row['Unique ID']

    if pd.notna(parent_id):
        # Convert parent to float for comparison with Unique ID
        try:
            parent_id = float(parent_id)
        except:
            continue

        if parent_id not in children_map:
            children_map[parent_id] = []
        children_map[parent_id].append(unique_id)

# Function to count all descendants (direct and indirect)
def count_descendants(node_id, children_map):
    if node_id not in children_map:
        return 0

    count = len(children_map[node_id])
    for child_id in children_map[node_id]:
        count += count_descendants(child_id, children_map)

    return count

# Find all Tier 1 categories
tier1_categories = df[df['Tier 1'].notna()].drop_duplicates('Tier 1')

# Count descendants for each Tier 1 category
tier1_descendants = {}
for _, row in tier1_categories.iterrows():
    tier1_name = row['Tier 1']
    unique_id = row['Unique ID']

    if pd.notna(unique_id):
        descendants = count_descendants(unique_id, children_map)
        tier1_descendants[tier1_name] = descendants

# Sort by descendant count
sorted_tier1 = sorted(tier1_descendants.items(), key=lambda x: x[1], reverse=True)

# Get the second largest
if len(sorted_tier1) >= 2:
    answer = sorted_tier1[1][0]
    print(answer)
